 WeakReference<Dialog> progressDialog=new WeakReference<>(null);WeakReference<TextView> progressText=new WeakReference<>(null);
 void progress(){MainActivity a=current();if(a==null)return;Dialog d=a.screenDialog();LinearLayout body=a.column();body.setPadding(a.dp(20),a.dp(20),a.dp(20),a.dp(20));TextView text=a.text(a.getString(R.string.update_downloading,Math.max(0,percent)),18,MainActivity.TEXT);body.addView(text);body.addView(a.text(a.getString(R.string.update_background),14,MainActivity.MUTED));body.addView(a.button(a.getString(R.string.update_close),d::dismiss),a.lp(-1,52));a.showScreen(d,body);progressDialog=new WeakReference<>(d);progressText=new WeakReference<>(text);}
